contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        uint before = address(this).balance;
        bool reverted1;
        try c.getFirstWithdrawalBonus(recipient) { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.getFirstWithdrawalBonus(recipient) { reverted2 = false; } catch { reverted2 = true; }
        assert(reverted1 || (address(this).balance == before + 100 && reverted2));
    }
    receive() external payable {}
}
